import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"14、【大有】 乾下離上","description":"周易闡真 - 14、【大有】 乾下離上","frontmatter":{"title":"14、【大有】 乾下離上","description":"周易闡真 - 14、【大有】 乾下離上"},"headers":[],"relativePath":"classics/chanzhen/015.md","filePath":"classics/chanzhen/015.md"}'),s={name:"classics/chanzhen/015.md"};function n(c,a,i,o,l,h){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：大有，柔得尊位大中，而上下應之，曰大有。其德剛健而文明，應乎天而時行，是以元亨。</p></blockquote><h1 id="_14、【大有】-乾下離上" tabindex="-1">14、【大有】 乾下離上 <a class="header-anchor" href="#_14、【大有】-乾下離上" aria-label="Permalink to “14、【大有】 乾下離上”">​</a></h1><p>初九：無交害，匪咎，艱則無咎。</p><p>九二：大車以載，有攸往，無咎。</p><p>九三：公用亨於天子，小人弗克。</p><p>九四：匪其彭，無咎。</p><p>六五：厥孚交如，威如，吉。</p><p>上九：自天佑之，吉，無不利。</p><h2 id="孔易闡真-​" tabindex="-1">孔易闡真 ​ <a class="header-anchor" href="#孔易闡真-​" aria-label="Permalink to “孔易闡真 ​”">​</a></h2><p>大象：火在天上，大有。君子以遏惡揚善，順天休命。</p><p>大有者，有之大也。上離火，下乾天，是火在天上，天得日而生者眾，日在天而照者遠，無物不在光天化日之下，大有之象也。</p><p>君子有見於此，知天命之性，渾然一理，萬善畢集，本大有也。因交後天，知識一開，先天受傷，由是善惡相雜，大有者而小有，小有者而無有矣。以是惡念一起，則遏而止息之；善念一生，則揚而滋長之，順乎天而休美其命焉。命之不休，由於不能順天；不順天，由於不能遏惡揚善。若能遏惡揚善，久而至善無惡，正氣常存，仍還當年完完全全天命之物事，無者有，而有者大矣。人生在世，惟命最大，有命則生，無命則死，不能休命，雖外之萬有，皆屬虛假。蓋天之所命於人者，一善而已。能休其命，即是順天；順天，即所以順命；休命，即所以休天。有天有命，有之最大。但有天有命，全在遏惡揚善工夫。遏惡揚善者，明也；順天休命者，健也。以健為體，以明為用，虛靈不昧，具眾理而應萬事，由明明德而歸於至善，渾然天理，性定命凝，有莫有於此，大莫大於此，世間一切身外之有，焉得而比之乎!</p><h2 id="悟元子註解-​" tabindex="-1">悟元子註解 ​ <a class="header-anchor" href="#悟元子註解-​" aria-label="Permalink to “悟元子註解 ​”">​</a></h2><p>用亨，亨作享。彭，音朋。</p><p>大有者，有之大也。卦德上離明，下乾健，明以行健，健中出明，愈健愈明，愈明愈健，故謂大有。此富有日新，嚴以治內之卦，承上否卦而來。否者陰氣用事，陽氣退位，認假失真，蔽塞靈竅，日晦日暗，本來天德全無矣。若欲復還天德，無中生有，非健明之道不能。</p><p>何謂健?一念純真，剛強不屈者是也。何謂明?燭照萬事，虛靈不昧者是也。能健則心堅志遠，無道不修，無德不立，而富有；能明則辨理透徹，真知確見，有善即遷，有過即改，而日新。既健且明，內有主宰，萬物難移，於是真履實踐，如天上有日，光照一切，無物不覆，無物能瞞，大地裡黃芽長遍，滿世界金花開綻，信步走去，頭頭是道，有之大而行之遠，元而未有不亨者也。</p><p>初九，在大有之始，所有不大，正當潛修密煉，不可因外物而傷內真者，是以無交害匪咎也。然不交於外物，倘有妄念內生，亦即是物，仍是有害有咎，惟艱以處之，煉己持心，假者去而真者來，不有者能有，方能始終一無所咎矣。此初有須當靜養於內也。</p><p>九二，剛健得中，已富有於內，如大車以載，能以任重，可以不為外物所傷矣。然德克於內，須驗於外，惟有攸往，事上境上，輕輕過去，不動不搖，方是大有，而內外一無所咎矣。此已有須當驗之於外也。</p><p>九三，剛居剛位，有之大而行之大，能以完全天德，如公用享於天子也。公用之享於天子者，剛正有為之才；修道之享於天者，剛正有為之德。以德享天，自命不凡，方且與天為配，何礙於天？</p><p>若夫剛而不正之小人，無而為有，予聖自雄，適以違天，焉能享天?此大有須貴剛之得正也。</p><p>九四，剛明兼備，有健不恃，有明不用，是匪其彭也。匪彭之剛明，外示不足，內常有餘，有者愈有，大者愈大，自無得而復失之咎。此大有尤貴剛而能柔也。</p><p>六五，柔順虛心，自信一己之無，而知他人之有，以柔求剛，借剛濟柔，是以厥孚交如，威如吉也。五本無威，以其能交於剛，雖愚必明，雖柔必強，無即能有，小即能大。此未有須當求人之有也。</p><p>上九，在大有之終，剛柔相當，健明如一，渾然天理，金丹凝結，我命由我不由天，是以自天佑之，吉無不利也。</p><p>天之所以命於人者，健德；人之所以順乎天者，明德。以明保健，天命常在，天命在而天即佑之。此大有須當全天之有也。然則大有實學，非健以治內，明以應外者不能行。既健且明，未有者而能有，已有者而能大，健明兩用，實腹虛心，富有日新之道盡矣。</p>',24)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
